const $=id=>document.getElementById(id),p=new URLSearchParams(location.search),id=foundations[p.get('lesson')]?p.get('lesson'):'torque',d=foundations[id],lang=p.get('lang')==='es'?'es':'en',en=lang==='en',t=(es,en)=>lang==='es'?es:en,fmt=v=>new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(v);
document.documentElement.lang=lang;let values=d.controls.map(c=>c.value),u=0,playing=false,view=null,last=0,visible=true,cut=true,saved=null;
$('orbit').textContent=t('Arrastra para girar · pellizca para acercar','Drag to orbit · pinch to zoom');$('cut').textContent=t('Corte abierto','Cutaway');$('cut').hidden=!['engine','press','pneumatic','motor','hydraulic'].includes(d.kind);$('reset').textContent=t('Restablecer','Reset');$('capture').textContent=t('Guardar lectura A','Save reading A');$('timeLabel').textContent=t('Recorre el experimento','Scrub the experiment');
const limitations={lever:t('Fuerza estática; la longitud visual del brazo sigue el control. No simula aceleración ni deformación.','Static force; visual arm length follows the control. No acceleration or deformation simulation.'),thermal:t('Modelo térmico concentrado: ambiente 20 °C, capacidad térmica 1000 J/K. La aguja es temperatura; no muestra movimiento mecánico.','Lumped thermal model: ambient 20 °C, heat capacity 1000 J/K. The indicator shows temperature, not mechanical motion.'),gas:t('Muestra sellada isotérmica: pV = 2 bar·L. Atmósfera aproximada 1 bar. Puntos esquemáticos, no simulación molecular.','Sealed isothermal sample: pV = 2 bar·L. Atmosphere approximated as 1 bar. Schematic dots, not molecular simulation.'),circuit:t('Circuito ideal de enseñanza. Puntos = sentido de corriente convencional; velocidad visual normalizada, no velocidad de electrones. El puente no incluye filtro. Arranque: carga resistiva fija 0,05 Ω, sin fuerza contraelectromotriz.','Ideal teaching circuit. Dots = conventional current direction; visual speed is normalized, not electron speed. Bridge has no filter. Starting model: fixed 0.05 Ω resistive load, no back EMF.'),motor:t('Motor idealizado de dos polos. Tres señales equilibradas normalizadas. La animación recorre un ciclo eléctrico lentamente; no reproduce las rpm físicas.','Idealised two-pole motor. Three balanced normalized signals. Animation shows one electrical cycle slowly, not physical rpm.'),opamp:t('Ganancia ideal con límites ±12 V. Un operacional real puede necesitar margen respecto a sus alimentaciones. Columnas = magnitud de tensión; consulta el signo en la onda.','Ideal gain with ±12 V limits. A real op amp may need headroom from its rails. Columns = voltage magnitude; read polarity in the wave.'),relief:t('Presión impuesta para explorar apertura; rampa ideal de 0 a 100 % entre ajuste y 1,2×ajuste. Bomba 6 L/min. No resuelve equilibrio con una carga real.','Imposed pressure to explore opening; ideal 0–100% ramp from setting to 1.2×setting. Pump 6 L/min. Does not solve equilibrium with a real load.'),hydraulic:t('Carrera 100 mm, fuente ideal de caudal, sin compresibilidad ni transitorios. Al llegar al tope, el ciclo se reinicia; no se modela el circuito de fin de carrera. Área variable expresada en lecturas; geometría esquemática fija.','100 mm stroke, ideal flow source, no compressibility or transients. At the end, the cycle restarts; end-stop circuitry is not modelled. Variable area is shown in readings; schematic geometry stays fixed.'),pneumatic:t('Diámetro 40 mm, vástago 20 mm. Fuerza sin fricción. Movimiento prescrito para ver rutas: no representa la velocidad real ni se detiene por carga. Los colores indican suministro y escape, no presión absoluta.','40 mm bore, 20 mm rod. Force excludes friction. Prescribed motion shows paths: it is not actual speed and does not stall under load. Colours indicate supply/exhaust, not absolute pressure.'),press:t('Líquido ideal sin fugas. Área de entrada 2 cm². Mismo volumen desplazado; se desprecia rozamiento y compresibilidad.','Ideal leak-free liquid. Input area 2 cm². Equal displaced volume; ignores friction and compressibility.'),engine:t('Ciclo ideal de 720°, sin adelantos de válvula. Animación ralentizada a un ciclo cada 8 s; rpm solo determina la lectura de ciclos/s.','Ideal 720° cycle, no valve timing advance. Animation slowed to one cycle per 8 s; rpm only determines the cycles/s reading.'),gears:t('Pareja ideal, entrada 18 dientes, sin pérdidas. La animación muestra una vuelta de entrada por ciclo visual.','Ideal pair, 18-tooth input, no losses. Animation shows one input turn per visual cycle.')};$('limit').textContent=limitations[d.kind]+t(' Reproducción normalizada: un recorrido visual en 8 s; no es tiempo físico salvo el tiempo indicado en las lecturas.',' Normalized playback: one visual traversal in 8 s; not physical time except where specified in readings.');
function controls(){ $('controls').replaceChildren(...d.controls.map((c,i)=>{const label=document.createElement('label'),span=document.createElement('span'),input=document.createElement('input');input.type='range';Object.assign(input,{min:c.min,max:c.max,step:c.step,value:values[i]});input.dataset.index=i;span.textContent=c.label[lang]+' · '+fmt(values[i]);input.setAttribute('aria-label',c.label[lang]);input.oninput=()=>{values[i]=+input.value;span.textContent=c.label[lang]+' · '+fmt(values[i]);draw()};label.append(span,input);return label}));}
const signal=['ac','threephase','rectifier','opamp'].includes(id);$('scope').hidden=!signal;
function plot(m){if(!signal)return;const canvas=$('scope');canvas.width=Math.max(280,Math.round(canvas.clientWidth));const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,left=36,right=w-12,span=right-left;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#39505f';ctx.beginPath();ctx.moveTo(left,75);ctx.lineTo(right,75);ctx.stroke();ctx.fillStyle='#b8ceda';ctx.font='11px monospace';ctx.fillText(t('Un ciclo · fase →','One cycle · phase →'),left,143);const max=id==='threephase'?1:id==='opamp'?Math.max(12,values[0]):values[0];ctx.fillText('±'+fmt(max)+(id==='threephase'?' p.u.':' V'),4,14);const series=id==='threephase'?3:id==='ac'?1:2;for(let k=0;k<series;k++){ctx.strokeStyle=['#53dce9','#f6ae58','#b7a1ef'][k];ctx.beginPath();for(let i=0;i<=240;i++){const s=state(id,values,i/240),v=id==='threephase'?s.currents[k]:k?s.output:s.input,x=left+i/240*span,y=75-v/max*52;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}ctx.strokeStyle='#ffffff';ctx.beginPath();ctx.moveTo(left+u*span,20);ctx.lineTo(left+u*span,130);ctx.stroke();ctx.fillStyle='#53dce9';ctx.fillText(id==='threephase'?'A / B / C':t('Entrada / salida','Input / output'),Math.max(100,w-150),14);}
function comparison(m){if(!saved)return;const root=$('comparison');root.replaceChildren();const table=document.createElement('table'),head=document.createElement('tr');for(const title of [t('Magnitud','Quantity'),'A',t('Ahora','Now')]){const th=document.createElement('th');th.textContent=title;head.append(th)}table.append(head);m.read.forEach((r,i)=>{const tr=document.createElement('tr');for(const txt of [r[lang],fmt(saved.read[i].value)+' '+r.unit,fmt(r.value)+' '+r.unit]){const td=document.createElement('td');td.textContent=txt;tr.append(td)}table.append(tr)});root.append(table);}
function draw(){const m=state(id,values,u);view?.draw(m);$('readings').replaceChildren(...m.read.map(r=>{const el=document.createElement('div');el.className='reading';const small=document.createElement('small'),b=document.createElement('b');small.textContent=r[lang];b.textContent=fmt(r.value)+' '+r.unit;el.append(small,b);return el}));$('time').value=u*1000;$('play').textContent=playing?t('Pausar','Pause'):t('Reproducir','Play');$('phase').textContent=id==='fourstroke'?[t('Admisión','Intake'),t('Compresión','Compression'),t('Expansión','Power'),t('Escape','Exhaust')][m.phase]:d.kind==='pneumatic'?m.paths.join(' · '):Math.round(u*100)+' %';plot(m);comparison(m);window.foundationDebug=()=>({id,values:[...values],u,state:m,has3D:!!view,playing});}
$('time').oninput=()=>{playing=false;u=+$('time').value/1000;draw()};$('play').onclick=()=>{playing=!playing;last=0;draw()};$('cut').onclick=()=>{cut=!cut;view?.cut(cut);$('cut').setAttribute('aria-pressed',String(cut));draw()};$('reset').onclick=()=>{values=d.controls.map(c=>c.value);u=0;playing=false;saved=null;$('comparison').replaceChildren();$('captureStatus').textContent='';controls();draw()};$('capture').onclick=()=>{saved=state(id,values,u);$('captureStatus').textContent=t('A guardada al ','A saved at ')+Math.round(u*100)+' %. '+t('Cambia una condición y compara.','Change one condition and compare.');draw()};
new IntersectionObserver(([e])=>{visible=e.isIntersecting;last=0}).observe($('stage'));matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{playing=false;draw()});
controls();try{const {mount}=await import('./scene.mjs');view=mount($('stage'),d.kind,id,lang)}catch(e){$('stage').textContent=t('3D no disponible. Puedes usar los controles y lecturas.','3D unavailable. Controls and readings still work.');console.error(e)}draw();let lastDraw=0;function tick(now){if(playing&&visible&&!document.hidden){if(last)u=(u+Math.min((now-last)/1000,.1)/8)%1;last=now;}else last=0;if(visible&&!document.hidden&&now-lastDraw>40){draw();lastDraw=now}requestAnimationFrame(tick)}requestAnimationFrame(tick);
